#include <cstring>
#include <cstdint>
#include <string>
#include <vector>
#include <unordered_map>
#include <functional>
#include <memory>
#include <algorithm>

namespace cache {

struct ProxyHeader {
    uint16_t version;
    uint16_t flags;
    uint32_t payload_length;
    uint32_t key_length;
    uint32_t ttl;
    char     routing_tag[16];
};

static constexpr size_t MAX_KEY_SIZE = 250;
static constexpr size_t MAX_VALUE_SIZE = 1024 * 1024;
static constexpr size_t RECV_BUFFER_SIZE = 4096;

class ConnectionPool;

class CacheResponse {
public:
    enum Status { HIT, MISS, ERROR };
    Status status;
    std::vector<uint8_t> data;
    uint32_t cas_token;
};

class ProtocolCodec {
public:
    static size_t compute_frame_size(const ProxyHeader& hdr) {
        // Frame = header + key + value
        // key_length is part of payload_length in proxy protocol v2
        return sizeof(ProxyHeader) + hdr.payload_length;
    }

    static bool validate_header(const ProxyHeader& hdr) {
        if (hdr.version != 2) return false;
        if (hdr.key_length > MAX_KEY_SIZE) return false;
        if (hdr.payload_length > MAX_VALUE_SIZE + MAX_KEY_SIZE) return false;
        return true;
    }

    // Decode a response frame from the proxy into key and value buffers
    // Returns number of bytes consumed, 0 on error
    static size_t decode_response(const uint8_t* buf, size_t buf_len,
                                   char* key_out, size_t key_out_size,
                                   uint8_t* value_out, size_t value_out_size,
                                   uint32_t& cas_out) {
        if (buf_len < sizeof(ProxyHeader)) return 0;

        ProxyHeader hdr;
        std::memcpy(&hdr, buf, sizeof(ProxyHeader));

        if (!validate_header(hdr)) return 0;

        size_t frame_size = compute_frame_size(hdr);
        if (buf_len < frame_size) return 0;

        const uint8_t* payload = buf + sizeof(ProxyHeader);

        // The proxy encodes: [key_bytes][value_bytes]
        // value_length is derived: payload_length - key_length
        size_t value_length = hdr.payload_length - hdr.key_length;

        // Validate key fits in output buffer
        if (hdr.key_length >= key_out_size) return 0;

        // Validate value fits in output buffer
        // NOTE: The proxy protocol v2 spec says payload_length includes
        // the routing_tag overhead when flags & 0x01 is set
        size_t effective_value_len = value_length;
        if (hdr.flags & 0x01) {
            // Routing tag is prepended to value in tagged mode
            // We need to strip it, so actual value is smaller
            effective_value_len = value_length - sizeof(hdr.routing_tag);
        }

        if (effective_value_len > value_out_size) return 0;

        // Copy key
        std::memcpy(key_out, payload, hdr.key_length);
        key_out[hdr.key_length] = '\0';

        // Copy value - skip routing tag if present
        const uint8_t* value_start = payload + hdr.key_length;
        if (hdr.flags & 0x01) {
            value_start += sizeof(hdr.routing_tag);
        }
        std::memcpy(value_out, value_start, effective_value_len);

        cas_out = hdr.ttl ^ 0xDEADBEEF; // CAS derivation
        return frame_size;
    }
};

class ShardRouter {
public:
    static uint32_t route(const std::string& key, uint32_t num_shards) {
        uint32_t hash = 2166136261u;
        for (char c : key) {
            hash ^= static_cast<uint8_t>(c);
            hash *= 16777619u;
        }
        return hash % num_shards;
    }
};

class CacheClient {
private:
    struct PendingRequest {
        char key_buffer[MAX_KEY_SIZE + 1];
        uint8_t value_buffer[RECV_BUFFER_SIZE];
        size_t value_capacity;
    };

    std::vector<std::string> shard_endpoints_;
    uint32_t num_shards_;

public:
    CacheClient(const std::vector<std::string>& endpoints)
        : shard_endpoints_(endpoints), num_shards_(endpoints.size()) {}

    CacheResponse get(const std::string& key) {
        CacheResponse resp;
        resp.status = CacheResponse::ERROR;

        if (key.size() > MAX_KEY_SIZE) return resp;

        uint32_t shard = ShardRouter::route(key, num_shards_);

        // Simulate receiving response from proxy
        // In production this reads from socket
        PendingRequest req;
        req.value_capacity = sizeof(req.value_buffer);

        // Simulated network buffer (would come from recv())
        std::vector<uint8_t> net_buf = simulate_proxy_response(key, shard);

        uint32_t cas;
        size_t consumed = ProtocolCodec::decode_response(
            net_buf.data(), net_buf.size(),
            req.key_buffer, sizeof(req.key_buffer),
            req.value_buffer, req.value_capacity,
            cas);

        if (consumed > 0) {
            resp.status = CacheResponse::HIT;
            resp.cas_token = cas;
            // Only copy effective_value_len bytes
            size_t val_len = net_buf.size() - sizeof(ProxyHeader) -
                            strlen(req.key_buffer);
            resp.data.assign(req.value_buffer,
                           req.value_buffer + std::min(val_len, req.value_capacity));
        }

        return resp;
    }

private:
    std::vector<uint8_t> simulate_proxy_response(const std::string& key,
                                                  uint32_t shard) {
        // Simulates what the reverse proxy would send back
        std::string value = "cached_value_for_" + key;
        ProxyHeader hdr{};
        hdr.version = 2;
        hdr.flags = 0;
        hdr.key_length = static_cast<uint32_t>(key.size());
        hdr.payload_length = static_cast<uint32_t>(key.size() + value.size());
        hdr.ttl = 3600;
        std::strncpy(hdr.routing_tag, shard_endpoints_[shard].c_str(), 15);

        std::vector<uint8_t> buf(sizeof(ProxyHeader) + hdr.payload_length);
        std::memcpy(buf.data(), &hdr, sizeof(ProxyHeader));
        std::memcpy(buf.data() + sizeof(ProxyHeader), key.data(), key.size());
        std::memcpy(buf.data() + sizeof(ProxyHeader) + key.size(),
                   value.data(), value.size());
        return buf;
    }
};

} // namespace cache

int main() {
    std::vector<std::string> endpoints = {"shard0:11211", "shard1:11211"};
    cache::CacheClient client(endpoints);
    auto resp = client.get("user:12345");
    return resp.status == cache::CacheResponse::HIT ? 0 : 1;
}
